<?php require_once __DIR__."/../config/auth.php";require_role(["admin"]);$pdo=db();$sup=$pdo->query("SELECT id,name FROM suppliers ORDER BY name")->fetchAll();$ps=$pdo->query("SELECT id,name_en,sku,purchase_price FROM products WHERE is_active=1 ORDER BY name_en")->fetchAll();if($_SERVER["REQUEST_METHOD"]==="POST"){try{check_csrf($_POST["csrf"]??"");$pdo->beginTransaction();$sub=0;$items=[];foreach($_POST["product"] as $k=>$id){$q=(float)$_POST["qty"][$k];$c=(float)$_POST["cost"][$k];if($q>0){$sub+=$q*$c;$items[]=[$id,$q,$c];}}if(!$items)throw new Exception("Add items.");$disc=min($sub,max(0,(float)$_POST["discount"]));$total=$sub-$disc;$paid=max(0,(float)$_POST["paid"]);$bal=max(0,$total-$paid);$no="PUR-".date("YmdHis")."-".random_int(100,999);$pdo->prepare("INSERT INTO purchases(purchase_no,supplier_id,user_id,subtotal,discount,total,paid,balance,status) VALUES(?,?,?,?,?,?,?,?,?)")->execute([$no,(int)$_POST["supplier"],user()["id"],$sub,$disc,$total,$paid,$bal,$paid>=$total?"paid":($paid?"partial":"unpaid")]);$pid=$pdo->lastInsertId();$ii=$pdo->prepare("INSERT INTO purchase_items(purchase_id,product_id,qty,unit_cost,line_total) VALUES(?,?,?,?,?)");$up=$pdo->prepare("UPDATE products SET stock_qty=stock_qty+?,purchase_price=? WHERE id=?");foreach($items as [$id,$q,$c]){$ii->execute([$pid,$id,$q,$c,$q*$c]);$up->execute([$q,$c,$id]);}$pdo->prepare("UPDATE suppliers SET balance=balance+? WHERE id=?")->execute([$bal,(int)$_POST["supplier"]]);$pdo->commit();$_SESSION["flash"]=["type"=>"ok","msg"=>"Purchase saved."];}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$_SESSION["flash"]=["type"=>"bad","msg"=>$e->getMessage()];}redirect("purchases.php");}include __DIR__."/partials/header.php";?><header><h1><?=t("المشتريات والاستلام","Purchases & Receiving")?></h1></header><div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Supplier<select name="supplier"><?php foreach($sup as $s):?><option value="<?=$s["id"]?>"><?=e($s["name"])?></option><?php endforeach;?></select></label><?php for($i=0;$i<5;$i++):?><div class="purchase"><select name="product[]"><option value="">Product</option><?php foreach($ps as $p):?><option value="<?=$p["id"]?>"><?=e($p["name_en"])?></option><?php endforeach;?></select><input name="qty[]" type="number" step=".001" placeholder="Qty"><input name="cost[]" type="number" step=".01" placeholder="Cost"></div><?php endfor;?><div class="form"><input name="discount" type="number" step=".01" placeholder="Discount"><input name="paid" type="number" step=".01" placeholder="Paid"></div><button class="btn primary">Save Purchase</button></form></div><?php include __DIR__."/partials/footer.php";?>